import { Chess } from './src/chess'

const cases: Array<[string, string]> = [
  ['p', 'a8'],
  ['p', 'h8'],
  ['p', 'a1'],
  ['p', 'h1'],
]

for (const [color, sq] of cases) {
  const chess = new Chess()
  chess.put({ type: 'p', color: color as 'w' | 'b' }, sq as any)
  try {
    const moves = chess.moves({ square: sq as any, verbose: true })
    console.log(`${color}${sq}: OK`, moves.map((m) => m.san))
  } catch (e) {
    console.log(`${color}${sq}: ERROR`, (e as Error).message)
  }
}

